"""Writes slices/status.json (and the status fields of slices/manifest.json): one status per slice, with the pass that signed it, for the builder's
place-masters tool. Reconciled with the art director's consolidated list (2026-10-08). python3 -I tools/status.py"""
import json, re
m = json.load(open("slices/manifest.json")); S = {}
FR = {"120x112", "120x96", "184x104", "184x112", "184x256", "184x304", "376x264"}
def sign(n, status, sig, note=""): S[n] = {"status": status, "signed_in": sig, "note": note}
for n in m:
    if re.match(r"rail-tab-fill-", n): sign(n, "new", None, "the rail rule of design-pods-relayout 29b6dc9: one fill per state, no lit rim, no teal; awaiting verdict")
    elif re.match(r"rail-tab-", n): sign(n, "withdrawn", None, "signed in pass 4; superseded by rail-tab-fill-* (the rail rule of 29b6dc9 takes the lit rim and the teal away)")
    elif n in ("room-bench-stage", "room-cradle"): sign(n, "signed", "pass 4", "re-cut to the layout of design-pods-relayout 29b6dc9 (pool on x 632)" if n == "room-bench-stage" else "")
    elif n in ("room-cradle-front", "room-shelf"): sign(n, "signed", "pass 7b", "re-cut for the new rectangle (shelf 488,368,288,72)" if n == "room-shelf" else "")
    elif re.match(r"plate-name-\d+x24$", n): sign(n, "signed", "pass 7b", "the 20 px name on its plate (the 0.6 tone signed in pass 6)")
    elif re.match(r"pod-(large|medium|small|well)-unknown", n): sign(n, "new", None, "the unknown pod: body #8a8a8e, accent #b8b8bc, no pattern, the band on; awaiting verdict")
    elif re.match(r"pod-(large|medium|small)-", n): sign(n, "signed", "pass 6", "layers signed across passes 4 to 7b; the 33 are standing")
    elif n.startswith("pod-well-"): sign(n, "new", None, "the well pod at 32x48, the pod centred vertically (rows about 6 to 41) as the art director asked; awaiting verdict")
    elif n.startswith("trait-picture-frame-"):
        size = re.search(r"(\d+x\d+)", n).group(1); kind = "sealed" if n.endswith("-sealed") else "unread" if n.endswith("-unread") else "plain"
        if size == "232x312": sign(n, "signed", "pass 6", "confirmed signed by the art director, not placed (the portrait frame is withdrawn from the layout)")
        elif size in ("184x304", "184x112", "120x112"): sign(n, "withdrawn", None, "the old Read picture sizes are withdrawn (design-pods-relayout 29b6dc9)")
        elif size in ("224x352", "224x160", "104x160", "104x96", "104x64"): sign(n, "signed", "pass 8 (d767daa verdict)", "224x352 and 224x160 are capped by the spec change (no picture larger than the pod's box: 144x176, 176x144)" if size in ("224x352", "224x160") else "")
        elif size == "176x144": sign(n, "withdrawn", None, "the two-trait picture is 104x160 now (design-pods-relayout 92fb6c7d)")
        elif size == "112x112": sign(n, "new", None, "the find picture frame of a sealed chapter at (224,296); awaiting verdict")
        elif size in FR: sign(n, "signed", {"plain": "pass 3", "unread": "pass 4", "sealed": "pass 6"}[kind])
        elif size == "232x312": sign(n, "signed", "pass 6", "the portrait frame and its states" + ("" if kind != "plain" else " (the plain frame is not named in the consolidated list; signed with its states in pass 6)"))
        else: sign(n, "new", None, "new size of design-pods-relayout 29b6dc9 (the Read page's grid); awaiting verdict")
    elif n == "ring-column": sign(n, "withdrawn", None, "the 160 px column of the earlier layout; replaced by ring-column-112x522")
    elif n == "ring-hatch": sign(n, "withdrawn", None, "the 112x56 slice of the earlier layout; replaced by ring-hatch-80x56")
    elif n == "stamp-label-120x120": sign(n, "signed", "pass 1")
    elif re.match(r"plate-message-", n): sign(n, "signed", "pass 2")
    elif n in ("frame-top-bar-1024x40", "frame-bottom-line-1024x38"): sign(n, "signed", "pass 1", "excluded from placing (the frame redesign)")
    elif re.match(r"rail-emblem-(coat|face|stamina|glow|character)-", n): sign(n, "signed", "emblems round 3")
    elif re.match(r"rail-emblem-(shape|movement|charge)-", n): sign(n, "signed", "emblems round 4")
    elif re.match(r"rail-emblem-", n): sign(n, "signed", "pass 20 (the pass 17 tail)", "Legs & tail: tail-a cropped, prongs hanging; the splayed tuft rejected; the rounds end here")
    elif n == "page-pane-408x440": sign(n, "withdrawn", None, "signed in pass 1, withdrawn with the page's re-layout (the Read page is 256 wide); Compare still uses 408")
    elif n == "room-stamp-case": sign(n, "withdrawn", None, "the old 176x328 size; the case is now 152x152")
    elif n == "room-stamp-case-152x152": sign(n, "signed", "pass 8 (d767daa verdict)", "with a condition: the front glass over the label (room-stamp-case-152x152-front)")
    elif n == "room-stamp-case-152x152-front": sign(n, "new", None, "the front glass over the label; awaiting verdict")
    elif re.match(r"(frame-(room|companion|sun|lamp|cap)-|face-)", n): sign(n, "new", None, "a mark of the Station frame (design-station-frame); awaiting verdict")
    elif n == "page-mark-new-10": sign(n, "new", None, "the new-to-the-field-guide mark as pods.json now specifies it: a flat bone dot 6x6, 1 px white lit edge, no keyline; awaiting verdict")
    elif n == "page-pane-256x440": sign(n, "new", None, "re-cut as a clean nine-slice (insets 16; serves 440, 264 and 248 high); signed in pass 8 as the painted pane, awaiting verdict on the regularised one")
    elif n in ("ring-column-112x522", "ring-hatch-80x56"): sign(n, "signed", "pass 8 (d767daa verdict)", "re-cut for design-pods-relayout 29b6dc9")
    elif n == "ring-well-empty": sign(n, "withdrawn", None, "the 64x64 slice; re-exported as ring-well-empty-80x80 (the art director: pad to 80x80 centred on (40,40))")
    elif n.startswith("mibi-halo-"): sign(n, "new", None, "the halo figure, round 2 (the light painted by the image tool over the silhouette); awaiting the verdict")
    elif n in ("place-meadow-48x48", "place-pond-48x48"): sign(n, "signed", "places round 1", "")
    elif n.startswith("place-") and n.endswith("-48x48"): sign(n, "new", None, "the collection overview place picture, redone in round 2; awaiting verdict")
    elif n == "ring-well-empty-80x80": sign(n, "new", None, "re-export of the signed ring-well-empty only, padded to 80x80; awaiting verdict")
    elif n == "page-new-mark-12x12": sign(n, "withdrawn", None, "superseded by page-mark-new-10 (now a 6x6 flat bone dot)")
    elif re.match(r"ring-well-(selected|idle)", n) or n == "glint-star-12x12" or re.match(r"ring-arc-idle-", n): sign(n, "signed", "well rings verdict")
    elif re.match(r"ring-arc-selected-", n): sign(n, "new", None, "pass 16: repainted as a painted gauge (soft groove, soft ticks, 1 px feathered cuts) after the owner saw a jagged ring; signed in pass 8 as the carved version; awaiting verdict")
    elif re.match(r"ring-well-(selected|idle)|ring-arc-|glint-star", n): sign(n, "new", None, "the well rings from the concept; awaiting verdict")
    else: sign(n, "stand-in" if False else "unclassified", None, "")
json.dump(S, open("slices/status.json", "w"), indent=1)
for n, v in S.items(): m[n].update({"status": v["status"], "signed_in": v["signed_in"], "status_note": v["note"]})
json.dump(m, open("slices/manifest.json", "w"), indent=1)
from collections import Counter; print(Counter(v["status"] for v in S.values())); print([n for n, v in S.items() if v["status"] == "unclassified"])
